const e=[{id:"pull-up",name_en:"Pull-Up",name_es:"Dominadas",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps","Forearms"],equipment:"bodyweight",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Hang from the bar with an overhand grip slightly wider than your shoulders, arms fully straight and legs together.","Brace your core and squeeze your glutes so your body stays in one line without swinging.","Pull your shoulder blades down first, pull until your chin clears the bar, then lower over 2-3 seconds to a dead hang.","Don't kip with your legs or cut reps short with your elbows still bent at the bottom.","Lower yourself to a full hang at the end of the set instead of dropping from the top."],squeeze_cue:"Drive your elbows down into your back pockets and squeeze your lats hard as your chin clears the bar.",aliases:[],origin:"new"},{id:"pull-up-wide-grip",name_en:"Pull-Up (Wide Grip)",name_es:"Dominadas (agarre ancho)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Rear Delts","Biceps"],equipment:"bodyweight",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Grip the bar overhand about 1.5x shoulder width and hang with your arms straight and shoulders engaged.","Lift your chest toward the bar and keep your elbows pointing out and down, not forward.","Pull until your upper chest nears the bar, pause briefly, then lower over 2-3 seconds to straight arms.","Don't go so wide that you lose range of motion or your shoulders shrug up toward your ears.","Narrow your grip if a wide hand position causes shoulder discomfort at the bottom."],squeeze_cue:"Pull your elbows down and out to your hips and squeeze the outer edges of your lats like closing a pair of wings.",aliases:[],origin:"new"},{id:"neutral-grip-weighted-chin-ups",name_en:"Pull-Up (Neutral Grip)",name_es:"Dominadas (agarre neutro)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Biceps","Upper Back","Forearms"],equipment:"bodyweight",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Hang from the parallel handles with your palms facing each other and your arms fully extended.","Keep your ribs down and lean your torso back slightly as you pull up.","Pull with your elbows tight to your sides until your chin clears the handles, then lower over 2-3 seconds.","Don't shrug at the start; set your shoulder blades down before you bend your elbows.","If you add weight, secure the belt or dumbbell so it doesn't swing between your legs."],squeeze_cue:"Drive your elbows straight down to your ribs and squeeze your lats as if crushing an orange in each armpit.",aliases:[],origin:"existing"},{id:"reverse-grip-chin-up-weighted",name_en:"Chin-Up",name_es:"Dominadas supinas",body_region:"Back",primary_muscles:["Lats","Biceps"],secondary_muscles:["Upper Back","Forearms"],equipment:"bodyweight",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Grip the bar shoulder-width with palms facing you and hang with your arms straight.","Keep your torso steady and your elbows in front of your body, pointing at the floor.","Pull until your chin is over the bar, then lower over 2-3 seconds all the way to a full hang.","Don't stop halfway on the way down; full extension trains the lats in their stretched position.","Add load in small jumps only when you can complete every rep from a dead hang."],squeeze_cue:"Pull your elbows down to your hips and squeeze your lats and biceps together as your chest rises to the bar.",aliases:["chin"],origin:"existing"},{id:"machine-assisted-pull-up",name_en:"Machine Assisted Pull-Up",name_es:"Dominadas asistidas en máquina",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps"],equipment:"machine",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Set the counterweight, place your knees or feet on the platform and grab the top handles.","Keep your torso upright and your chest up without leaning onto the platform.","Pull until your chin passes the handles, pause for a second, then lower over 3 seconds to straight arms.","Don't use so much assistance that the platform launches you; reduce it as you get stronger.","Keep both hands on the handles as you step on and off so the platform doesn't jolt."],squeeze_cue:"Drive your elbows down to your sides and squeeze your lats at the bottom, holding the contraction for a beat.",aliases:[],origin:"new"},{id:"band-assisted-pull-up",name_en:"Band Assisted Pull-Up",name_es:"Dominadas asistidas con banda",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps"],equipment:"band",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Loop the band over the bar and place a knee or foot in it before hanging with an overhand grip.","Keep your body in a straight line and your core tight so the band doesn't swing you.","Pull until your chin is over the bar, then lower over 2-3 seconds so the band doesn't snap you up.","Don't rely on a thick band forever; switch to a lighter one once you hit your target reps.","Check the band for nicks and make sure it's securely looped before every set."],squeeze_cue:"Pull your elbows into your back pockets and squeeze your lats hard at the top instead of letting the band lift you.",aliases:[],origin:"new"},{id:"lat-pulldown",name_en:"Cable Lat Pulldown (Wide Grip)",name_es:"Jalón al pecho en polea (agarre ancho)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps","Rear Delts"],equipment:"cable",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Set the thigh pad snug over your legs and grip the bar overhand, wider than your shoulders.","Lean back a few degrees with your chest up and your lower back neutral.","Pull the bar to your upper chest, pause for a second, then let it rise over 2-3 seconds until your lats stretch.","Don't pull the bar behind your neck or rock your torso back to move more weight.","Return the bar to the top before standing up so the plates don't slam."],squeeze_cue:"Pull your elbows down into your back pockets and squeeze your lats hard at the bottom.",aliases:[],origin:"existing"},{id:"neutral-grip-lat-pulldown",name_en:"Cable Lat Pulldown (Neutral Grip)",name_es:"Jalón al pecho en polea (agarre neutro)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps"],equipment:"cable",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Attach a neutral-grip handle, sit with your thighs under the pad and your arms fully extended.","Keep your chest up and your elbows close to your body, pointing at the floor.","Pull the handle to your sternum, pause briefly, then return over 2-3 seconds to full extension.","Don't round your back at the end of the pull to bring the handle closer to your chest.","Make sure the carabiner on the handle is fully closed before loading the stack."],squeeze_cue:"Drive your elbows down tight to your ribs and squeeze your lats as if pinning a newspaper under each arm.",aliases:[],origin:"existing"},{id:"single-arm-lat-pulldown",name_en:"Cable Lat Pulldown (Single-Arm)",name_es:"Jalón al pecho en polea (a una mano)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps"],equipment:"cable",movement_pattern:"pull vertical",mechanic:"compound",laterality:"unilateral",posture_tips:["Sit under the high pulley with a single handle and your working arm fully stretched overhead.","Keep your torso square and stable, without twisting toward the working side.","Drive your elbow down toward your hip on a slight diagonal, then let the arm rise over 2-3 seconds.","Don't compensate by leaning sideways; the movement should come from the shoulder and elbow.","Start with your weaker arm and match the reps on the other side."],squeeze_cue:"Pull your elbow down into your hip pocket and squeeze the lat on that side, feeling it shorten along your ribs.",aliases:[],origin:"existing"},{id:"cable-lat-pulldown-underhand-grip",name_en:"Cable Lat Pulldown (Underhand Grip)",name_es:"Jalón al pecho en polea (agarre supino)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Biceps","Upper Back"],equipment:"cable",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Grip a straight bar shoulder-width with palms facing you and lock your thighs under the pad.","Keep your chest up with a slight lean back, without over-arching your lower back.","Pull the bar to your lower chest with elbows tucked, pause, then return over 2-3 seconds to a full stretch.","Don't turn it into a biceps curl: think about driving the elbows down, not bending the wrists.","Use a weight you can control on the way up without it lifting you off the seat."],squeeze_cue:"Drive your elbows down beside your ribs and squeeze your lower lats hard as the bar touches your chest.",aliases:[],origin:"new"},{id:"reverse-grip-lats-machine",name_en:"Machine Lat Pulldown (Underhand Grip)",name_es:"Jalón en máquina (agarre supino)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Biceps","Upper Back"],equipment:"machine",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Adjust the seat so you can reach the handles with arms extended and palms facing you.","Brace firmly against the chest or thigh pad and keep your back neutral.","Pull the handles down along the machine's arc, pause for a second, then return over 2-3 seconds to a full stretch.","Don't lift off the seat or pad to gain range with momentum.","Check that the weight pin is fully inserted before you start."],squeeze_cue:"Pull your elbows down toward your hips and squeeze your lats at the bottom as if tucking them into your back pockets.",aliases:[],origin:"existing"},{id:"plate-loaded-lat-pulldown",name_en:"Plate-Loaded Lat Pulldown",name_es:"Jalón al pecho en máquina de discos",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps","Rear Delts"],equipment:"plate-loaded",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Load the plates evenly on both sides, lock your thighs under the pad and grab the handles.","Keep your chest up and your torso still throughout the movement.","Pull the handles to the sides of your chest, pause, then let them rise over 2-3 seconds until your arms are straight.","Don't let the handles fly up at the top; control the lowering phase on every rep.","Load and unload plates with the machine at rest, alternating sides so it doesn't tip out of balance."],squeeze_cue:"Drive your elbows down and back to your sides and squeeze your lats hard at the bottom of each pull.",aliases:[],origin:"new"},{id:"barbell-bent-over-row",name_en:"Barbell Bent-Over Row",name_es:"Remo inclinado con barra",body_region:"Back",primary_muscles:["Upper Back","Lats"],secondary_muscles:["Rear Delts","Biceps","Lower Back"],equipment:"barbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Grip the bar overhand slightly wider than shoulders, knees soft, and hinge your torso to about 45 degrees.","Keep your back neutral and neck in line, eyes on the floor slightly ahead of you.","Row the bar to your navel, pause for a second, then lower over 2 seconds to straight arms without moving your torso.","Don't stand up on each rep to heave the bar up with momentum.","Reduce the load as soon as you can no longer hold a neutral back."],squeeze_cue:"Drive your elbows back and squeeze your shoulder blades together like holding a pencil between them.",aliases:[],origin:"new"},{id:"bb-bent-over-reverse-grip-rows",name_en:"Barbell Bent-Over Row (Underhand Grip)",name_es:"Remo inclinado con barra (agarre supino)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps","Lower Back"],equipment:"barbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Grip the bar shoulder-width with palms facing forward and hinge at the hips with soft knees.","Keep your torso angled and locked, core braced and the bar close to your thighs.","Row the bar to your lower abs with elbows close, pause, then lower over 2 seconds to straight arms.","Don't flex your wrists or turn the row into a biceps curl.","Lift the bar off the floor with a neutral back and your legs, never with a rounded back."],squeeze_cue:"Drive your elbows back past your hips and squeeze your lats hard, as if pinning a book under each arm.",aliases:[],origin:"existing"},{id:"barbell-pendlay-row",name_en:"Barbell Pendlay Row",name_es:"Remo Pendlay con barra",body_region:"Back",primary_muscles:["Upper Back","Lats"],secondary_muscles:["Rear Delts","Biceps","Lower Back"],equipment:"barbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Set up with the bar on the floor over midfoot and your torso nearly parallel to the ground.","Keep your back flat and hips high, holding the same torso angle from rep to rep.","Row the bar explosively to your stomach, then lower it to the floor under control and pause dead still each rep.","Don't lift your torso to help the bar up; if you need to, the load is too heavy.","Lower the bar under control rather than dropping it, keeping your back flat as it touches down."],squeeze_cue:"Rip the bar to your stomach and squeeze your shoulder blades together hard for a split second at the top.",aliases:[],origin:"new"},{id:"smith-machine-bent-over-row",name_en:"Smith Machine Bent-Over Row",name_es:"Remo inclinado en máquina Smith",body_region:"Back",primary_muscles:["Upper Back","Lats"],secondary_muscles:["Rear Delts","Biceps"],equipment:"smith-machine",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Set the safeties at knee height, grip the bar overhand and hinge your torso from the hips.","Position yourself so the bar travels straight to your stomach without hitting your thighs.","Row the bar to your navel, pause for a second, then lower over 2 seconds to straight arms.","Don't stand too close or too far from the bar; the fixed path demands precise positioning.","Rotate the bar to re-rack it on the hooks before letting go at the end."],squeeze_cue:"Drive your elbows toward the ceiling and pinch your shoulder blades together as the bar touches your stomach.",aliases:[],origin:"new"},{id:"barbell-seal-row",name_en:"Barbell Seal Row",name_es:"Remo foca con barra",body_region:"Back",primary_muscles:["Upper Back","Lats"],secondary_muscles:["Rear Delts","Biceps"],equipment:"barbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Lie face down on a high flat bench with the bar beneath you and your arms hanging straight.","Keep your chest and hips on the bench and your head in line with your torso.","Row the bar until it touches the underside of the bench, pause, then lower over 2-3 seconds to full extension.","Don't lift your chest off the bench to gain range; you lose support and tension.","Make sure the bench is stable on boxes or supports before you lie on it."],squeeze_cue:"Pull your elbows up past your torso and squeeze your shoulder blades together as the bar taps the bench.",aliases:[],origin:"new"},{id:"barbell-t-bar-row",name_en:"Barbell T-Bar Row",name_es:"Remo en T con barra",body_region:"Back",primary_muscles:["Upper Back","Lats"],secondary_muscles:["Rear Delts","Biceps","Lower Back"],equipment:"barbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Straddle the anchored bar with a V-handle under the plates, knees bent and hips hinged.","Keep your torso at about 45 degrees and your back neutral throughout the pull.","Row the handle to your lower chest, pause for a second, then lower over 2 seconds until your arms are straight.","Don't load big plates that shorten your range or force you to swing.","Secure the end of the bar in a landmine or corner so it can't slide."],squeeze_cue:"Drive your elbows back and squeeze your mid-back together as if cracking a walnut between your shoulder blades.",aliases:[],origin:"new"},{id:"plate-loaded-t-bar-row-chest-supported",name_en:"Plate-Loaded T-Bar Row (Chest-Supported)",name_es:"Remo en T en máquina de discos (con apoyo de pecho)",body_region:"Back",primary_muscles:["Upper Back","Lats"],secondary_muscles:["Rear Delts","Biceps"],equipment:"plate-loaded",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Step onto the platform, rest your chest on the pad and grab the handles with straight arms.","Keep your chest on the pad and your neck neutral without lifting your head.","Row the handles toward your torso, pause for a second, then lower over 2-3 seconds to straight arms.","Don't peel your chest off the pad to push with your legs at the end of the pull.","Step on and off the platform only with the load in its resting position."],squeeze_cue:"Drive your elbows behind your body and squeeze your shoulder blades together hard while your chest stays glued to the pad.",aliases:[],origin:"new"},{id:"barbell-meadows-row",name_en:"Barbell Meadows Row",name_es:"Remo Meadows con barra",body_region:"Back",primary_muscles:["Lats","Upper Back"],secondary_muscles:["Rear Delts","Biceps","Forearms"],equipment:"barbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"unilateral",posture_tips:["Stand perpendicular to the anchored bar, grip the end overhand and rest your free forearm on your knee.","Keep your hips high, torso hinged and back neutral without rotating.","Row the bar end toward your hip with the elbow flared, pause, then lower over 2 seconds until your lat stretches.","Don't twist your torso open to move the load; keep rotation minimal.","Use smaller plates for more range of motion and anchor the bar securely before you start."],squeeze_cue:"Pull your elbow up and back toward your hip and squeeze your lat and upper back on that side at the top.",aliases:[],origin:"new"},{id:"dumbbell-row-single-arm",name_en:"Dumbbell Row (Single-Arm)",name_es:"Remo con mancuerna (a una mano)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Rear Delts","Biceps"],equipment:"dumbbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"unilateral",posture_tips:["Place one knee and one hand on the bench, with the dumbbell hanging under the shoulder of your free arm.","Keep your back flat and parallel to the floor, with your shoulders level.","Pull the dumbbell toward your hip brushing your side, pause, then lower over 2 seconds until your lat stretches.","Don't rotate your torso up on each rep to lift more weight.","Pick up and put down the dumbbell with a neutral back while supported on the bench."],squeeze_cue:"Pull your elbow back to your hip like starting a lawnmower and squeeze your lat hard at the top.",aliases:[],origin:"new"},{id:"dumbbell-bent-over-row",name_en:"Dumbbell Bent-Over Row",name_es:"Remo inclinado con mancuernas",body_region:"Back",primary_muscles:["Upper Back","Lats"],secondary_muscles:["Rear Delts","Biceps","Lower Back"],equipment:"dumbbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Hold a dumbbell in each hand, soften your knees and hinge your torso from the hips.","Keep your back neutral and your weight spread across your whole foot.","Row both dumbbells toward your waist with elbows close, pause, then lower over 2 seconds.","Don't let your head drop or your shoulders round forward on the way down.","Switch to the chest-supported version if your lower back tires before your upper back."],squeeze_cue:"Drive both elbows back and squeeze your shoulder blades together as if pinching a coin between them.",aliases:[],origin:"new"},{id:"dumbbell-chest-supported-row",name_en:"Dumbbell Chest-Supported Row",name_es:"Remo con mancuernas con apoyo de pecho",body_region:"Back",primary_muscles:["Upper Back"],secondary_muscles:["Lats","Rear Delts","Biceps"],equipment:"dumbbell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Lie face down on a bench inclined to about 30-45 degrees with a dumbbell in each hand.","Keep your chest on the pad and your toes planted on the floor so you don't slide.","Drive your elbows back until your shoulder blades meet, hold 1 second, then lower over 2-3 seconds.","Don't crane your neck to look forward; keep your gaze toward the floor.","Set the dumbbells on the floor before getting up from the bench."],squeeze_cue:"Pull your elbows toward the ceiling and squeeze your shoulder blades together like holding a pencil between them.",aliases:[],origin:"new"},{id:"kettlebell-row-single-arm",name_en:"Kettlebell Row (Single-Arm)",name_es:"Remo con kettlebell (a una mano)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps","Forearms"],equipment:"kettlebell",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"unilateral",posture_tips:["Take a staggered stance, brace your free hand on a bench or thigh and grip the kettlebell handle.","Keep your torso hinged and stable, with your hips square to the floor.","Row the kettlebell toward your hip with a straight wrist, pause, then lower over 2 seconds.","Don't let the kettlebell swing between reps; come to a stop at the bottom of each one.","Grip the handle firmly and make sure you have clear space around you as you row."],squeeze_cue:"Drive your elbow back into your hip pocket and squeeze your lat hard while the bell stays close to your side.",aliases:[],origin:"new"},{id:"seated-cable-row",name_en:"Cable Seated Row",name_es:"Remo sentado en polea",body_region:"Back",primary_muscles:["Upper Back"],secondary_muscles:["Lats","Biceps","Rear Delts"],equipment:"cable",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit with your feet on the platform, knees slightly bent, holding the V-handle with arms extended.","Keep your torso upright and still, chest up and shoulders away from your ears.","Row the handle to your stomach, hold 1 second, then extend over 2-3 seconds letting your shoulders reach forward.","Don't rock your torso back and forth to move the weight with your lower back.","Grab and release the handle with your knees bent so you don't yank on your lower back."],squeeze_cue:"Drive your elbows back past your ribs and squeeze your shoulder blades together like holding a pencil between them.",aliases:[],origin:"existing"},{id:"wide-grip-cable-row",name_en:"Cable Seated Row (Wide Grip)",name_es:"Remo sentado en polea (agarre ancho)",body_region:"Back",primary_muscles:["Upper Back"],secondary_muscles:["Rear Delts","Lats","Biceps"],equipment:"cable",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Attach a long bar, grip it overhand wider than your shoulders and sit with your back upright.","Keep your elbows flared about 60-70 degrees from your torso and your chest up.","Row the bar to your lower chest, hold 1 second, then return over 2-3 seconds.","Don't shrug at the end of the pull; finish with your shoulder blades, not your neck.","Choose a weight you can control on the return without it pulling you forward."],squeeze_cue:"Pull your elbows wide and back and squeeze your mid-back and rear delts as if bending the bar into a U.",aliases:[],origin:"existing"},{id:"cable-seated-row-underhand-grip",name_en:"Cable Seated Row (Underhand Grip)",name_es:"Remo sentado en polea (agarre supino)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps"],equipment:"cable",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Grip a straight bar shoulder-width with palms up and sit tall with knees slightly bent.","Keep your elbows tight to your body and your torso locked during the pull.","Row the bar to your navel, pause for a second, then return over 2-3 seconds until your arms are straight.","Don't lift or flare your elbows; you'd lose the emphasis on the lats.","Keep your wrists straight and in line with your forearms throughout the set."],squeeze_cue:"Drive your elbows back past your hips and squeeze your lats hard, feeling them tighten along your lower ribs.",aliases:[],origin:"new"},{id:"single-hand-cable-unilateral-rows",name_en:"Cable Seated Row (Single-Arm)",name_es:"Remo sentado en polea (a una mano)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps"],equipment:"cable",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"unilateral",posture_tips:["Sit facing the pulley with a single handle and your arm extended forward.","Keep your shoulders level and torso stable, allowing only a slight rotation.","Row the handle toward your hip, pause, then extend over 2-3 seconds letting your shoulder reach forward.","Don't twist your whole torso to finish the rep; the work should come from your back.","Start with your weaker side and brace your free hand on your thigh for stability."],squeeze_cue:"Drive your elbow back into your hip pocket and squeeze the lat on that side as the handle reaches your waist.",aliases:[],origin:"existing"},{id:"wide-grip-cable-chest-pulls",name_en:"Cable Pull to Chest (Wide Grip)",name_es:"Jalón en polea al pecho (agarre ancho)",body_region:"Back",primary_muscles:["Upper Back"],secondary_muscles:["Rear Delts","Lats","Biceps"],equipment:"cable",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Face the pulley with a long bar at chest height and take a wide overhand grip.","Keep your torso upright and chest up, elbows at or slightly below shoulder height.","Pull the bar to your chest flaring your elbows, hold 1 second, then return over 2-3 seconds to straight arms.","Don't lean back to bring the bar closer; your torso shouldn't move.","Set the pulley height and weight before starting so you can pull without neck tension."],squeeze_cue:"Pull your elbows wide and back and squeeze your rear delts and mid-back together as the bar reaches your chest.",aliases:[],origin:"existing"},{id:"wide-grip-supp-seated-row",name_en:"Machine Chest-Supported Row (Wide Grip)",name_es:"Remo con apoyo de pecho en máquina (agarre ancho)",body_region:"Back",primary_muscles:["Upper Back"],secondary_muscles:["Rear Delts","Lats","Biceps"],equipment:"machine",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Adjust the seat and pad so the wide handles sit at chest height with your arms extended.","Keep your chest on the pad and your elbows flared out to the sides.","Row back until your elbows pass your torso, hold 1 second, then return over 2-3 seconds.","Don't pull your chest off the pad at the end of each rep to gain range.","Check that the pin is fully inserted and the seat is locked before every set."],squeeze_cue:"Pull your elbows wide and behind you and squeeze your upper back as if pinching a tennis ball between your shoulder blades.",aliases:[],origin:"existing"},{id:"neutral-grip-supp-rows",name_en:"Machine Chest-Supported Row (Neutral Grip)",name_es:"Remo con apoyo de pecho en máquina (agarre neutro)",body_region:"Back",primary_muscles:["Upper Back"],secondary_muscles:["Lats","Biceps","Rear Delts"],equipment:"machine",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Sit with your chest against the pad and grab the vertical handles with palms facing each other.","Keep your back neutral and your elbows close to your body throughout the row.","Pull until your elbows are behind your torso, pause, then straighten your arms over 2-3 seconds.","Don't shrug your shoulders or jut your head forward at the end of the pull.","Let the weight return to rest under control when you finish the set."],squeeze_cue:"Drive your elbows back along your sides and squeeze your shoulder blades together like holding a pencil between them.",aliases:[],origin:"existing"},{id:"unilateral-supp-rows-reverse-grip",name_en:"Machine Chest-Supported Row (Underhand Grip, Single-Arm)",name_es:"Remo con apoyo de pecho en máquina (agarre supino, a una mano)",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Upper Back","Biceps"],equipment:"machine",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"unilateral",posture_tips:["Rest your chest on the pad and grab one handle palm up with your arm extended.","Keep your chest fixed and your shoulders square to the pad, without twisting your torso.","Drive your elbow back along your side toward your hip, pause, then return over 2-3 seconds to a full stretch.","Don't push against the machine with your free hand to assist the pull.","Train both sides with the same load and reps to keep things balanced."],squeeze_cue:"Pull your elbow back past your hip and squeeze the lat on that side as if tucking it into your back pocket.",aliases:[],origin:"existing"},{id:"plate-loaded-low-row",name_en:"Plate-Loaded Low Row",name_es:"Remo bajo en máquina de discos",body_region:"Back",primary_muscles:["Lats","Upper Back"],secondary_muscles:["Biceps","Rear Delts"],equipment:"plate-loaded",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Set the seat so your chest is against the pad and grab the low handles with your arms extended.","Keep your chest on the pad and your torso upright without leaning back.","Row the handles toward your hips, pause for a second, then return over 2-3 seconds until your back stretches.","Don't shorten the range; let your shoulder blades spread apart on every stretch.","Load plates evenly and strip them when you finish to leave the machine safe."],squeeze_cue:"Drive your elbows back toward your hips and squeeze your lats and mid-back together at the end of the pull.",aliases:[],origin:"new"},{id:"plate-loaded-high-row",name_en:"Plate-Loaded High Row",name_es:"Remo alto en máquina de discos",body_region:"Back",primary_muscles:["Lats","Upper Back"],secondary_muscles:["Rear Delts","Biceps"],equipment:"plate-loaded",movement_pattern:"pull vertical",mechanic:"compound",laterality:"bilateral",posture_tips:["Lock your thighs under the pad and grab the high handles with your arms extended overhead.","Keep your chest up with a slight forward lean, without arching your lower back.","Pull the handles down and back to your chest, pause, then return over 2-3 seconds to the top.","Don't let the weight lift you off the seat on the way up.","Adjust the thigh pad so you're locked in before loading heavy plates."],squeeze_cue:"Drive your elbows down and back behind you and squeeze your lats and shoulder blades together at the bottom.",aliases:[],origin:"new"},{id:"inverted-row",name_en:"Inverted Row",name_es:"Remo invertido",body_region:"Back",primary_muscles:["Upper Back"],secondary_muscles:["Lats","Rear Delts","Biceps"],equipment:"bodyweight",movement_pattern:"pull horizontal",mechanic:"compound",laterality:"bilateral",posture_tips:["Set up under a bar fixed at hip height, grip it overhand and extend your body with heels on the floor.","Keep your body rigid like a plank, with glutes and abs squeezed.","Pull until your chest touches the bar, hold 1 second, then lower over 2 seconds to straight arms.","Don't let your hips sag or rise before your chest during the pull.","Make sure the rack or Smith machine bar is securely locked before hanging from it."],squeeze_cue:"Pull your chest to the bar and squeeze your shoulder blades together as if trying to crack a walnut between them.",aliases:[],origin:"new"},{id:"db-pull-overs",name_en:"Dumbbell Pullover",name_es:"Pullover con mancuerna",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Chest","Triceps"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Lie on the bench holding one dumbbell with both hands over your chest, elbows slightly bent.","Keep your ribs down and your lower back stable, without arching as the weight lowers.","Arc the dumbbell behind your head over 2-3 seconds until you feel a stretch, then bring it back over your chest.","Don't bend and straighten your elbows each rep; keep the elbow angle fixed.","Cup the dumbbell under the top plate with interlocked hands so it can't slip."],squeeze_cue:"Pull the dumbbell back over your chest by driving your upper arms toward your hips, squeezing your lats.",aliases:[],origin:"existing"},{id:"ez-bar-pullover",name_en:"EZ-Bar Pullover",name_es:"Pullover con barra EZ",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Chest","Triceps"],equipment:"ez-bar",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Lie on a flat bench with the EZ bar over your chest using a narrow overhand grip.","Keep your head down, feet planted and elbows slightly bent throughout the arc.","Lower the bar behind your head over 2-3 seconds until your lats stretch, then pull it back over your chest.","Don't go past the point you can control or arch your back to chase more range.","Use a moderate load; the bar passes over your face and you must be able to stop it at any point."],squeeze_cue:"Sweep the bar back over your chest by pulling your elbows toward your hips, squeezing your lats like closing a book.",aliases:[],origin:"new"},{id:"machine-pullover",name_en:"Machine Pullover",name_es:"Pullover en máquina",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Triceps","Chest"],equipment:"machine",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Set the seat so your shoulders line up with the machine's pivot and rest your elbows on the pads.","Keep your back against the pad and fasten the seat belt if the machine has one.","Drive your elbows down in an arc to your sides, hold 1 second, then return over 2-3 seconds until your lats stretch.","Don't pull with your hands; press through the back of your upper arms.","Lighten the load and recheck the pivot alignment if you feel the work in the front of your shoulders."],squeeze_cue:"Drive the backs of your arms down to your sides and squeeze your lats hard as if pinning a towel under each arm.",aliases:[],origin:"new"},{id:"cable-straight-arms-pull-downs",name_en:"Cable Straight-Arm Pulldown",name_es:"Jalón con brazos rectos en polea",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Triceps","Rear Delts"],equipment:"cable",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Face the high pulley with a straight bar or rope, arms extended and torso leaning slightly forward.","Keep your elbows nearly locked and your back neutral, hips pushed slightly back.","Sweep the bar down in an arc to your thighs, hold 1 second, then let it rise over 2-3 seconds to eye level.","Don't bend your elbows and turn it into a triceps pushdown.","Step back after grabbing the bar so the load doesn't pull you forward at the start."],squeeze_cue:"Sweep your hands down to your thighs and squeeze your lats hard, feeling them wrap around your ribs at the bottom.",aliases:["straight-bb-straight-arms-pull-downs"],origin:"existing"},{id:"band-straight-arm-pulldown",name_en:"Band Straight-Arm Pulldown",name_es:"Jalón con brazos rectos con banda",body_region:"Back",primary_muscles:["Lats"],secondary_muscles:["Triceps","Rear Delts"],equipment:"band",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Anchor the band overhead, grab it with both hands and step back until there's tension.","Keep your arms straight, chest up and a slight hip hinge.","Sweep your hands down in an arc to your hips, hold 1 second, then return over 2-3 seconds to shoulder height.","Don't shrug as the band pulls your arms back up.","Check the anchor and the band's condition; if it slips it can snap back at you."],squeeze_cue:"Press your hands down to your hips and squeeze your lats hard at the bottom as if pushing the band into your thighs.",aliases:[],origin:"new"},{id:"barbell-shrug",name_en:"Barbell Shrug",name_es:"Encogimientos con barra",body_region:"Back",primary_muscles:["Traps"],secondary_muscles:["Upper Back","Forearms"],equipment:"barbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Take the bar from a rack at thigh height with a shoulder-width overhand grip.","Keep your arms straight, chest up and chin neutral, without looking up.","Raise your shoulders straight up toward your ears, hold 1-2 seconds, then lower over 2 seconds to a full stretch.","Don't roll your shoulders in circles; the movement is straight up and down.","Unrack the bar from mid-thigh height instead of lifting it off the floor."],squeeze_cue:"Lift your shoulders straight to your ears and pause, feeling your upper traps squeeze.",aliases:[],origin:"new"},{id:"dumbbell-shrug",name_en:"Dumbbell Shrug",name_es:"Encogimientos con mancuernas",body_region:"Back",primary_muscles:["Traps"],secondary_muscles:["Upper Back","Forearms"],equipment:"dumbbell",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Stand with a dumbbell at each side and your palms facing your body.","Keep your arms relaxed and straight, neck long and eyes forward.","Shrug as high as possible, hold 1-2 seconds at the top, then lower over 2 seconds until your traps stretch.","Don't bend your elbows to help; your arms are just hooks.","Use straps if your grip gives out before your traps rather than dropping the dumbbells."],squeeze_cue:"Shrug your shoulders up as if trying to touch your ears and squeeze your upper traps hard at the top.",aliases:[],origin:"new"},{id:"hex-bar-shrug",name_en:"Hex-Bar Shrug",name_es:"Encogimientos con barra hexagonal",body_region:"Back",primary_muscles:["Traps"],secondary_muscles:["Upper Back","Forearms"],equipment:"hex-bar",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Step inside the hex bar, grab the high handles and stand up with it using your legs.","Keep your torso upright and your shoulders in line with the handles, without leaning.","Shrug your shoulders straight up, hold 1-2 seconds at the top, then lower over 2 seconds.","Don't roll your shoulders forward; think about lifting them vertically toward your ears.","Pick up and set down the bar with a neutral back, just like a deadlift."],squeeze_cue:"Drive your shoulders straight up to your ears and squeeze your upper traps as if shrugging a heavy yoke.",aliases:[],origin:"new"},{id:"smith-machine-shrug",name_en:"Smith Machine Shrug",name_es:"Encogimientos en máquina Smith",body_region:"Back",primary_muscles:["Traps"],secondary_muscles:["Upper Back","Forearms"],equipment:"smith-machine",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Set the safeties at mid-thigh, grip the bar overhand and unrack it by rotating your wrists.","Keep your body close to the bar and your back straight throughout.","Raise your shoulders along the bar's path, hold 1-2 seconds at the top, then lower over 2 seconds.","Don't cut the range short with excessive loads; range matters more than weight.","Set the safety stops just below the starting position before you begin."],squeeze_cue:"Pull your shoulders up toward your ears and squeeze your upper traps hard at the top before lowering.",aliases:[],origin:"new"},{id:"cable-shrug",name_en:"Cable Shrug",name_es:"Encogimientos en polea",body_region:"Back",primary_muscles:["Traps"],secondary_muscles:["Upper Back","Forearms"],equipment:"cable",movement_pattern:"isolation",mechanic:"isolation",laterality:"bilateral",posture_tips:["Attach a straight bar to the low pulley, grip it overhand and stand close to the stack.","Keep your arms straight and your torso vertical without leaning toward the pulley.","Shrug toward your ears against the cable, hold 1-2 seconds, then lower over 2-3 seconds to a full stretch.","Don't bounce at the bottom; use the cable's constant tension through the whole range.","Plant your feet firmly and stand close enough that the cable doesn't pull you off balance."],squeeze_cue:"Lift your shoulders straight to your ears and squeeze your upper traps hard while the cable pulls you down.",aliases:[],origin:"new"}];export{e as default};
